def solve_ledger(text):
    lines = iter(text.splitlines())
    n, q = map(int, next(lines).split())
    tree = [0] * (n + 1)
    def add(i, delta):
        while i <= n:
            tree[i] += delta
            i += i & -i
    def prefix(i):
        answer = 0
        while i > 0:
            answer += tree[i]
            i -= i & -i
        return answer
    for i, value in enumerate(map(int, next(lines).split()), 1):
        add(i, value)
    output = []
    for _ in range(q):
        command, a, b = next(lines).split()
        a, b = int(a), int(b)
        if command == "A":
            add(a, b)
        else:
            output.append(str(prefix(b) - prefix(a-1)))
    return "\n".join(output)

